# Regenerate the review report from the committed gates and read-only spawn audit.
$ErrorActionPreference = 'Stop'
. "$PSScriptRoot\common.ps1"
$job = Join-Path $Root 'jobs\track-ux'
$arming = Get-Content -LiteralPath "$job\arming.json" -Raw | ConvertFrom-Json
$spawns = Get-Content -LiteralPath "$job\spawns.json" -Raw | ConvertFrom-Json
$audit = Get-Content -LiteralPath "$job\spawns.json.run.json" -Raw | ConvertFrom-Json
$trackGate = Get-Content -LiteralPath "$job\track-checks.json" -Raw | ConvertFrom-Json
$mapGate = Get-Content -LiteralPath "$job\map-checks.json" -Raw | ConvertFrom-Json
if ($audit.result -ne 'PASS' -or $trackGate.result -ne 'PASS' -or $mapGate.result -ne 'PASS') { throw 'A required gate did not pass.' }
if ((Get-FileHash -LiteralPath "$Root\bot\build\pathtracing.jar").Hash -ne $trackGate.modSha256) { throw 'Build differs from the tested mod.' }
if ((Get-FileHash -LiteralPath "$job\maps.json").Hash -ne $audit.outputSha256) { throw 'Corrected map registry differs from its audit.' }
$maps = Get-Content -LiteralPath "$job\maps.json" -Raw | ConvertFrom-Json
$source = Get-Content -LiteralPath (Join-Path $Rig 'maps.json') -Raw | ConvertFrom-Json
if ($maps.Count -ne $source.Count -or $maps.Count -ne $spawns.Count) { throw 'The corrected file must contain every map.' }
for ($i = 0; $i -lt $maps.Count; $i++) {
  foreach ($property in $source[$i].PSObject.Properties) {
    if ($property.Name -eq 'spawn') { continue }
    if (($maps[$i].($property.Name) | ConvertTo-Json -Compress) -cne ($property.Value | ConvertTo-Json -Compress)) { throw "Changed map metadata: $($source[$i].name) $($property.Name)" }
  }
  if (($maps[$i].PSObject.Properties.Name -join ',') -cne ($source[$i].PSObject.Properties.Name -join ',')) { throw 'Map schema changed.' }
}
function Distribution($Values) {
  $v = @($Values | Sort-Object)
  $n = $v.Count
  if ($n -eq 0 -or @($v | Where-Object { $null -eq $_ }).Count) { throw 'Incomplete arming events cannot be reported as completed.' }
  $median = if ($n % 2) { $v[[int][Math]::Floor($n/2)] } else { ($v[$n/2-1] + $v[$n/2]) / 2 }
  "$n | $($v[0]) | $median | $($v[[int][Math]::Ceiling(.90*$n)-1]) | $($v[[int][Math]::Ceiling(.99*$n)-1]) | $($v[-1])"
}
function Base-Line([string]$File, [string]$Text) {
  $lines = @(& git -C $Root show "$($arming.baselineCommit):$File")
  for ($i = 0; $i -lt $lines.Count; $i++) { if ($lines[$i].Contains($Text)) { return ($i + 1) } }
  throw "Missing before source anchor: $Text"
}
function Current-Line([string]$File, [string]$Text) {
  (Select-String -LiteralPath (Join-Path $Root $File) -SimpleMatch $Text | Select-Object -First 1).LineNumber
}
$oldFailure = Base-Line 'bot/src/pathtracing/Tracks.java' 'if (mode.state() == TrackMode.State.FAILED && selected != null)'
$oldReturn = Base-Line 'bot/src/pathtracing/Tracks.java' 'if (mode.active() && !mode.ready())'
$oldFailState = Base-Line 'bot/src/pathtracing/TrackMode.java' 'state = State.FAILED;'
$fixed = Current-Line 'bot/src/pathtracing/TrackHumanRace.java' 'mode.exit(); // Roll back'
$none = @($spawns | Where-Object status -eq 'NO_STANDABLE_CELL')
$lines = [Collections.Generic.List[string]]::new()
$lines.Add('# Track UX: completed')
$lines.Add('')
$lines.Add("Restore root cause (before commit $($arming.baselineCommit)): bot/src/pathtracing/Tracks.java:$oldFailure cleared the selection with restoreHuman=false after a failed kit, while bot/src/pathtracing/TrackMode.java:$oldFailState retained FAILED and the original session. The early return at Tracks.java:$oldReturn then prevented all future selection. /track restore was the only path back to IDLE. The frozen before test reproduces this: $($arming.beforeFailedKit).")
$lines.Add("The shared lifecycle now rolls back the refused kit once (bot/src/pathtracing/TrackHumanRace.java:$fixed). It keeps the reason visible on A and allows the next contact to arm. Crash, disconnect and unfinished-exit sessions restore automatically, then arm on the same A contact. A capture refusal is latched rather than silently retried. Explicit exit still suppresses entry until stepping off A. The earlier report's suppression explanation was incomplete: asynchronous successful recovery already passed in the baseline; FAILED was the stuck path.")
$lines.Add('')
$lines.Add('## Arming, first sampled contact with A to detector armed and action bar Armed: go')
$lines.Add('')
$lines.Add("Headless FIFO packet simulation, not a live latency claim. One-way transport delays cycle through 1..4 client ticks; first contact phases span 1..20; cold catalog selection and stale-session recovery are included. The production lifecycle, transaction, detector and UI sinks run together. The before transaction is read directly from the frozen commit; BeforeRace reproduces its original selection/return branches. Full samples and replay inputs: arming.json, generated by bot/tests/test-tracks.ps1. Median uses the middle pair; percentiles use nearest rank.")
$lines.Add('')
$lines.Add('| Case | n | min | median | p90 | p99 | max |')
$lines.Add('|---|---:|---:|---:|---:|---:|---:|')
foreach ($case in @(@('Before fresh', $arming.beforeFresh), @('After fresh', $arming.afterFresh), @('Before stale session', $arming.beforeStale), @('After stale session', $arming.afterStale), @('After repeated stick reset (one-way delay 1)', $arming.afterRepeatedReset))) {
  $lines.Add("| $($case[0]) | $(Distribution $case[1]) |")
}
$lines.Add('')
$lines.Add('Waits removed: the 20-tick initial catalog polling interval; deferring capture/restore progress until the next client tick; the extra inventory-to-target transition (restoration included); the periodic time-packet refill barrier. Each sample reads the current track definitions; packet callbacks advance the transaction immediately.')
$lines.Add('Waits retained: authoritative inventory capture; creative-mode confirmation (or ordered creative command before slots when already creative); slot readback; target-mode confirmation; completion packets for both one-tick instant-health and saturation effects; final authoritative inventory/mode/refill query. Recovery adds the corresponding restore transaction before fresh capture. Detector arming happens in the first client sample after readiness. The existing server-confirmation refusal deadline remains; no delay, tolerance or retry was added. Mojang effect application-before-expiry and removal-packet emission are checked against the staged game jar by TrackMixinAudit.')
$lines.Add('')
$lines.Add('## Checked spawn delivery')
$lines.Add('')
$lines.Add("scripts/audit-map-spawns.ps1 checked Test-Port before and after the read-only audit: port $($audit.port) closed. maps.json is the full corrected registry for the integrator to compare and copy; all other fields and map order match the rig. spawns.json records each source spawn and hashes of the actual map-region inputs. The audit uses Mojang NbtIo, data fixing for older chunks, collision shapes for clear feet/head cells and upper-face support below. It chooses minimum vertical distance in the same column, upwards first on a tie.")
$lines.Add('')
$lines.Add('| Map | Old spawn | New spawn | Result |')
$lines.Add('|---|---|---|---|')
foreach ($row in $spawns) { $lines.Add("| $($row.name) | $($row.old -join ', ') | $($row.new -join ', ') | $($row.status) |") }
$lines.Add('')
$lines.Add("Columns with no standable cell for Julien: $(if ($none.Count) { ($none.name -join ', ') } else { 'none' }). the_drop_2 uses the legacy SpawnX/Y/Z fields and explicitly stores 0,0,0; the imported dimension confirms that cell is standable. Both legacy fields and the current spawn compound have tests.")
$lines.Add('')
$lines.Add('## Checks and in-game handoff')
$lines.Add('')
$lines.Add('bot/build.ps1, bot/tests/test-tracks.ps1 and bot/tests/test-maps.ps1 pass. New coverage uses the actual command trees (all five existing-name track arguments, new-name omission and map names plus overworld), exact prefix filtering, all three recovery origins, refused kit/capture rollback, continuous action-bar states, immediate untimed departure chat, counted finishes, repeated resets and refusal to audit an open port. Compiled mod wiring is checked too. No game, server or client was launched. The rig registry, tracks, runs and world regions were only read. Pre-existing fixture-region modifications and backups in this worktree were left alone.')
$lines.Add('')
$lines.Add('Try in game after integration: tab-complete each track command and /map; enter A and leave as soon as Armed: go appears; reset repeatedly with the stick; leave during Arming and check the immediate untimed chat; reconnect on A after an interrupted race and check automatic recovery; visit diversity_parkour and frosted_ices. A refused kit shows its reason, restores the original automatically and permits a new attempt after stepping off A and returning.')
[IO.File]::WriteAllText((Join-Path $job 'last.md'), ($lines -join "`n") + "`n", [Text.UTF8Encoding]::new($false))
Write-Output "Report: $job\last.md"
